/**
 * @method
 * @name grd_pageResult_fmt_column10
 * @description grd page Result fmt column10 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_pageResult_fmt_column10 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_pageResult");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "ldMktTpCd") ?? '') : '');
        if (v === '1') { return '<a href="javascript:void(0)"' + (false ? ' class="lnk"' : '') + '>' + "수정요청 수정요청 수정요청 수정요청 -" + '</a>'; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_pageResult.column10" }); return String(data ?? ''); }
};

