/**
 * @method
 * @name pubofrSchdl
 * @description pubofr Schdl 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {String} ldMktTpCd ldMktTpCd
 * @param {String} listTpClssCd listTpClssCd
 * @param {*} tp tp
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.pubofrSchdl = async function (bzProcsNo, ldMktTpCd, listTpClssCd, tp) {
    $c.util.getComponent('dma_pubofrSchdlReq').set('method', "listPrelmInvstgWrite");
    $c.util.getComponent('dma_pubofrSchdlReq').set('page', "00");
    $c.util.getComponent('dma_pubofrSchdlReq').set('bzProcsNo', "" + bzProcsNo);
    $c.util.getComponent('dma_pubofrSchdlReq').set('ldMktTpCd', "" + ldMktTpCd);
    $c.util.getComponent('dma_pubofrSchdlReq').set('listTpClssCd', "" + listTpClssCd);
    $c.util.getComponent('dma_pubofrSchdlReq').set('view', tp);
    await scwin.tx_fn_pubofrSchdl();
};

/**
 * @method
 * @name cap
 * @description cap 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {String} ldMktTpCd ldMktTpCd
 * @param {String} listTpClssCd listTpClssCd
 * @param {*} tp tp
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cap = async function (bzProcsNo, ldMktTpCd, listTpClssCd, tp) {
    $c.util.getComponent('dma_pubofrSchdlReq').set('method', 'loadAttachForm');
    $c.util.getComponent('dma_pubofrSchdlReq').set('page', '20');
    $c.util.getComponent('dma_pubofrSchdlReq').set('bzProcsNo', "" + bzProcsNo);
    $c.util.getComponent('dma_pubofrSchdlReq').set('ldMktTpCd', "" + ldMktTpCd);
    $c.util.getComponent('dma_pubofrSchdlReq').set('listTpClssCd', "" + listTpClssCd);
    $c.util.getComponent('dma_pubofrSchdlReq').set('view', tp);
    await scwin.tx_fn_cap('/listInvstg/lplAttach.do');
};

/**
 * @method
 * @name submit
 * @description submit 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {*} code code
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.submit = async function (bzProcsNo, code) {
    if (await $c.win.confirm('제출하시겠습니까?')) {
        $c.util.getComponent('dma_pubofrSchdlReq').set('method', "listPrelmInvstgList");
        $c.util.getComponent('dma_pubofrSchdlReq').set('page', "list");
        $c.util.getComponent('dma_pubofrSchdlReq').set('bzProcsNo', bzProcsNo);
        $c.util.getComponent('dma_pubofrSchdlReq').set('code', code);
        $c.util.getComponent('dma_pubofrSchdlReq').set('type', "submit");
        await scwin.tx_fn_submit();
    }
};

/**
 * @method
 * @name prtDepo
 * @description prt Depo 처리
